using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Service registration ---
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tool implementations ---
var notebook = new ResearchNotebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (
            [Description("The search query to look up on the web")] string query
        ) =>
        {
            return WebSearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a given query and returns a summary of results."),

    AIFunctionFactory.Create(
        (
            [Description("A descriptive title for the note")] string title,
            [Description("The content to save")] string content
        ) =>
        {
            notebook.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notebook.GetNotes();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all previously saved research notes."),
};

// --- Agent setup ---
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI research assistant that searches the web, takes notes, and produces summaries.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    },
    loggerFactory,
    sp);

var runOptions = new ChatClientAgentRunOptions
{
    MaxIterations = 10,
};

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (MAF)        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research.          ║");
Console.WriteLine("║  Type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    notebook.Clear();

    var prompt = $"""
        Research the following topic by searching the web multiple times with different queries
        to gather comprehensive information. Save important findings as notes using the save_note tool.
        After gathering enough information (at least 2-3 searches), retrieve your notes and produce
        a well-structured summary with key findings and sources.

        Topic: {topic}
        """;

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    try
    {
        var session = await agent.CreateSessionAsync(null);

        await foreach (var update in agent.RunStreamingAsync(
            [new ChatMessage(ChatRole.User, prompt)],
            session,
            runOptions))
        {
            if (update.Text is { Length: > 0 } text)
            {
                Console.Write(text);
            }
        }

        Console.WriteLine("\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");

// --- Web search helper (uses DuckDuckGo Lite) ---
static async Task<string> WebSearchAsync(string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    try
    {
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
        var html = await http.GetStringAsync(url);

        var results = ParseDuckDuckGoResults(html);

        return results.Count == 0
            ? $"No results found for \"{query}\"."
            : $"Search results for \"{query}\":\n\n" +
              string.Join("\n\n", results.Take(5));
    }
    catch (Exception ex)
    {
        return $"Search failed for \"{query}\": {ex.Message}";
    }
}

static List<string> ParseDuckDuckGoResults(string html)
{
    var results = new List<string>();
    var spans = html.Split("<a rel=\"nofollow\"", StringSplitOptions.RemoveEmptyEntries);

    foreach (var span in spans.Skip(1).Take(5))
    {
        var titleEnd = span.IndexOf("</a>", StringComparison.Ordinal);
        if (titleEnd < 0)
        {
            continue;
        }

        var titleStart = span.IndexOf('>') + 1;
        var title = StripHtml(span[titleStart..titleEnd]);

        var hrefStart = span.IndexOf("href=\"", StringComparison.Ordinal);
        var link = string.Empty;
        if (hrefStart >= 0)
        {
            hrefStart += 6;
            var hrefEnd = span.IndexOf('"', hrefStart);
            link = span[hrefStart..hrefEnd];
        }

        // Extract snippet from the next <td> block
        var snippet = string.Empty;
        var snippetMarker = span.IndexOf("class=\"result-snippet\"", StringComparison.Ordinal);
        if (snippetMarker >= 0)
        {
            var snipStart = span.IndexOf('>', snippetMarker) + 1;
            var snipEnd = span.IndexOf("</td>", snipStart, StringComparison.Ordinal);
            if (snipEnd > snipStart)
            {
                snippet = StripHtml(span[snipStart..snipEnd]).Trim();
            }
        }

        if (!string.IsNullOrWhiteSpace(title))
        {
            results.Add($"- {title}\n  URL: {link}" +
                (string.IsNullOrEmpty(snippet) ? "" : $"\n  {snippet}"));
        }
    }

    return results;
}

static string StripHtml(string html)
{
    var sb = new StringBuilder();
    var inTag = false;
    foreach (var c in html)
    {
        if (c == '<') { inTag = true; continue; }
        if (c == '>') { inTag = false; continue; }
        if (!inTag) { sb.Append(c); }
    }

    return System.Net.WebUtility.HtmlDecode(sb.ToString());
}

// --- Notebook model ---
sealed class ResearchNotebook
{
    private readonly List<Note> _notes = [];

    public void AddNote(string title, string content) =>
        _notes.Add(new Note(title, content));

    public IReadOnlyList<Note> GetNotes() => _notes;

    public void Clear() => _notes.Clear();
}

