1. using System.ComponentModel;
2. using System.Text;
3. using Microsoft.Agents.AI;
4. using Microsoft.Extensions.AI;
5. using OpenAI;
6. 
7. // --- Configuration ---
8. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
9.     ?? throw new InvalidOperationException(
10.         "Set the OPENAI_API_KEY environment variable before running.");
11. 
12. const string modelId = "gpt-4o-mini-2024-07-18";
13. 
14. // --- Create the chat client via MEAI abstraction ---
15. var openAiClient = new OpenAIClient(apiKey);
16. IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();
17. 
18. // --- Tool implementations ---
19. var notebook = new ResearchNotebook();
20. 
21. var tools = new List<AITool>
22. {
23.     AIFunctionFactory.Create(
24.         (
25.             [Description("The search query to look up on the web")] string query
26.         ) =>
27.         {
28.             return WebSearchAsync(query);
29.         },
30.         "web_search",
31.         "Searches the web for information on a given query and returns a summary of results."),
32. 
33.     AIFunctionFactory.Create(
34.         (
35.             [Description("A descriptive title for the note")] string title,
36.             [Description("The content to save")] string content
37.         ) =>
38.         {
39.             notebook.AddNote(title, content);
40.             return $"Note saved: \"{title}\"";
41.         },
42.         "save_note",
43.         "Saves a research note with a title and content for later reference."),
44. 
45.     AIFunctionFactory.Create(
46.         () =>
47.         {
48.             var notes = notebook.GetNotes();
49.             return notes.Count == 0
50.                 ? "No notes saved yet."
51.                 : string.Join("\n\n", notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));
52.         },
53.         "get_notes",
54.         "Retrieves all previously saved research notes."),
55. };
56. 
57. // --- Agent setup ---
58. var agent = new ChatClientAgent(
59.     chatClient,
60.     new ChatClientAgentOptions
61.     {
62.         Name = "ResearchAgent",
63.         Description = "An AI research assistant that searches the web, takes notes, and produces summaries.",
64.         ChatOptions = new ChatOptions
65.         {
66.             Temperature = 0f,
67.             MaxOutputTokens = 2048,
68.             Tools = [.. tools],
69.         },
70.     });
71. 
72. var runOptions = new ChatClientAgentRunOptions();
73. 
74. // --- Interactive loop ---
75. Console.WriteLine("╔══════════════════════════════════════╗");
76. Console.WriteLine("║       AI Research Agent (MAF)        ║");
77. Console.WriteLine("╠══════════════════════════════════════╣");
78. Console.WriteLine("║  Enter a topic to research.          ║");
79. Console.WriteLine("║  Type 'quit' to exit.                ║");
80. Console.WriteLine("╚══════════════════════════════════════╝");
81. Console.WriteLine();
82. 
83. while (true)
84. {
85.     Console.Write("Research topic> ");
86.     var topic = Console.ReadLine()?.Trim();
87.     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
88.     {
89.         break;
90.     }
91. 
92.     notebook.Clear();
93. 
94.     var prompt = $"""
95.         Research the following topic by searching the web multiple times with different queries
96.         to gather comprehensive information. Save important findings as notes using the save_note tool.
97.         After gathering enough information (at least 2-3 searches), retrieve your notes and produce
98.         a well-structured summary with key findings and sources.
99. 
100.         Topic: {topic}
101.         """;
102. 
103.     Console.WriteLine($"\nResearching \"{topic}\"...\n");
104. 
105.     try
106.     {
107.         var session = await agent.CreateSessionAsync(cancellationToken: default);
108. 
109.         await foreach (var update in agent.RunStreamingAsync(
110.             [new ChatMessage(ChatRole.User, prompt)],
111.             session,
112.             runOptions))
113.         {
114.             if (update.Text is { Length: > 0 } text)
115.             {
116.                 Console.Write(text);
