         var snippet = string.Empty;
         var snippetMarker = span.IndexOf("class=\"result-snippet\"", StringComparison.Ordinal);
         if (snippetMarker >= 0)
         {
             var snipStart = span.IndexOf('>', snippetMarker) + 1;
             var snipEnd = span.IndexOf("</td>", snipStart, StringComparison.Ordinal);
             if (snipEnd > snipStart)
             {
                 snippet = StripHtml(span[snipStart..snipEnd]).Trim();
             }
         }

